""" 2.integrals.py
Given sample, computes radius and phases at origin."""

from math import *
tau = 2*pi
import numpy as np

def mod(z:complex)->float:
    """
    Given complex z, returns its module.
    """
    x = z.real
    y = z.imag
    return sqrt(x**2 + y**2)

def arg(z:complex)->float:
    """
    Given complex z, returns its argument.
    """
    x = z.real
    y = z.imag
    if x<0 and y>=0:
        return atan(y/x)+pi
    if x==0 and y>0:
        return pi/2
    if x>0:
        return atan(y/x)
    if x==0 and y<0:
        return -pi/2
    if x<0 and y<0:
        return atan(y/x)-pi
    if x==0 and y==0:
        return 0

def expi(x:float)->complex:
    """
    Given float x, computes exp(ix).
    """
    return complex(cos(x), sin(x))

