N = 100

Lz = []
for k in range(len(Lx)):
    Lz.append(complex(Lx[k], Ly[k]))

# Fourier coefficients are implemented in a dict[complex], whose keys are indexes and values coefficients.
c = {}

def integral(f, a:float=0, b:float=1, n:int=100)->complex:
    """
    Computes integral of f from a to b with a trapezoid method with n steps.
    f (function) : function to integrate
    a (float) : interval infimum
    b (float) : interval supremum
    n (int) : number of steps
    """
    assert n>0 and a<b
    pas = (b-a)/n

    integral = 0
    for k in range(n):
        x = a + k*pas
        integral += (f(x) + f(x+pas))
    return integral*pas/2

for n in range(-N, N+1):
    # We prefer to generate piecewise affine function to prevent numerical problems in case we are out of the Nyquist-Shannon's criteria.
    def integrand(t:float)->float:
        """
        Fucition
        f(t) = z(t)e^(-int)
        whose integral is the nth Fourier coefficient.
        We rebuild function from sample by linear interpolation.
        """
        L = len(Lz)
        if t<tau-1e-6:
            k = floor(t*(L-1)/tau)
        else:
            k = L-2
        tmin = k*tau/(len(Lz)-1)
        tmax = (k+1)*tau/(len(Lz)-1)
        try:
            return (Lz[k]+(t-tmin)*(Lz[k+1]-Lz[k])/(tmax-tmin))*expi(-n*t)
        except:
            print(n, k, t)

    c[n] = integral(integrand, 0, tau, 100*(abs(n)+1))
    # Display loading status on shell
    print(str(n) + '/' + str(N))

r, theta = {}, {}
for n in range(-N, N+1):
    r[n] = mod(c[n])
    theta[n] = arg(c[n])

print('r = '+str(r))
print('theta = '+str(theta))